import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, BoxGeometry, CircleGeometry, Color, DoubleSide } = THREE;

  const group = new Group();
  group.name = 'home-stat-tile';

  const colors = (config && config.intent && config.intent.visualSpec && config.intent.visualSpec.colors) || config.colors || {};
  const ink = new Color(colors.ink || '#16161d');
  const paper = new Color(colors.paper || '#e8ecf2');
  const accent = new Color(colors.accent || '#ff2a38');
  const surface = new Color(colors.surface || '#0b0b10');

  // --- Machinedmetal backing panel (stat tile surface) ---
  const panelGeo = new BoxGeometry(1.45, 1.45, 0.08);
  const panelMat = new MeshStandardNodeMaterial();
  panelMat.color.copy(surface).lerp(ink, 0.4);
  panelMat.metalness = 0.55;
  panelMat.roughness = 0.5;
  panelMat.clearcoat = 0.2;
  panelMat.clearcoatRoughness = 0.45;
  const panel = new Mesh(panelGeo, panelMat);
  panel.position.set(0, 0, -0.04);
  panel.castShadow = true;
  panel.receiveShadow = true;
  group.add(panel);

  // inner recessed face (subtle paper-tinted rim for machined contrast)
  const innerGeo = new BoxGeometry(1.3, 1.3, 0.085);
  const innerMat = new MeshStandardNodeMaterial();
  innerMat.color.copy(ink);
  innerMat.metalness = 0.5;
  innerMat.roughness = 0.62;
  innerMat.clearcoat = 0.15;
  const inner = new Mesh(innerGeo, innerMat);
  inner.position.set(0, 0, -0.02);
  group.add(inner);

  // --- Accent edge strip (focus-edge, machined chamfer read) ---
  const edgeGeo = new BoxGeometry(1.45, 0.045, 0.09);
  const edgeMat = new MeshStandardNodeMaterial();
  edgeMat.color.copy(accent);
  edgeMat.emissive.copy(accent);
  edgeMat.emissiveIntensity = 1.6;
  edgeMat.roughness = 0.35;
  edgeMat.metalness = 0.3;
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.set(0, 0.725, 0.0);
  group.add(edge);

  // --- Grounded contact shadow ---
  const shadowGeo = new CircleGeometry(0.95, 48);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.color.set(0x000000);
  shadowMat.transparent = true;
  shadowMat.opacity = 0.5;
  shadowMat.side = DoubleSide;
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -0.86, -0.06);
  group.add(shadow);

  // --- GLB machined core (gear-a) loaded for metric surface texture ---
  let glbScene = null;
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      glbScene = gltf && (gltf.scene || gltf);
      if (!glbScene) return;
      glbScene.traverse((o) => {
        if (o.isMesh && o.material) {
          if (o.material.metalness !== undefined) o.material.metalness = 0.5;
          if (o.material.roughness !== undefined) o.material.roughness = 0.55;
          if (o.material.clearcoat !== undefined) o.material.clearcoat = 0.18;
          if (o.material.color) o.material.color.copy(paper).multiplyScalar(0.85);
        }
      });
      glbScene.scale.setScalar(0.42);
      glbScene.position.set(0, 0.0, 0.05);
      glbScene.rotation.set(0.2, 0.4, 0);
      group.add(glbScene);
    }).catch(() => {});
  }

  // --- Cinematic primitive: parallax-scroll ---
  const primRefs = [];
  const primitives = (config && config.cinematicPrimitives) || [];
  for (const p of primitives) {
    if (p && p.name && ctx.primitives && typeof ctx.primitives[p.name] === 'function') {
      try {
        const r = ctx.primitives[p.name](group, p.params || {});
        if (r) primRefs.push(r);
      } catch (_) {}
    }
  }

  // --- Interactions ---
  const baseY = 0;
  let hoverTl = null;
  let pressTl = null;

  const handlers = {
    pointerover: () => {
      hoverTl && hoverTl.kill();
      hoverTl = gsap.timeline({ overwrite: true });
      hoverTl.to(group.position, { y: baseY + 0.15, duration: 0.6, ease: 'power3.out' }, 0);
      hoverTl.to(edge.material, { emissiveIntensity: 2.1, duration: 0.45, ease: 'power2.out' }, 0);
      hoverTl.to(group.rotation, { z: 0.04, duration: 0.5, ease: 'power3.out' }, 0);
    },
    pointerout: () => {
      hoverTl && hoverTl.kill();
      hoverTl = gsap.timeline({ overwrite: true });
      hoverTl.to(group.position, { y: baseY, duration: 0.45, ease: 'power3.out' }, 0);
      hoverTl.to(edge.material, { emissiveIntensity: 1.6, duration: 0.4, ease: 'power2.out' }, 0);
      hoverTl.to(group.rotation, { z: 0, duration: 0.5, ease: 'power3.out' }, 0);
    },
    click: () => {
      pressTl && pressTl.kill();
      pressTl = gsap.timeline({ overwrite: true });
      pressTl.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'power2.in' });
      pressTl.to(group.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.25, ease: 'power3.out' });
      pressTl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
      try {
        ctx.emit('hub-home.select', { source: 'home-stat-tile' });
      } catch (_) {}
    },
  };
  group.userData.handlers = handlers;

  // --- Cleanup ---
  group.userData.cleanup = () => {
    if (hoverTl) hoverTl.kill();
    if (pressTl) pressTl.kill();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(group.rotation);
    gsap.killTweensOf(edge.material);
    for (const r of primRefs) {
      if (r && typeof r.cleanup === 'function') try { r.cleanup(); } catch (_) {}
      if (r && r.timeline) try { r.timeline.kill(); } catch (_) {}
    }
    panelGeo.dispose();
    panelMat.dispose();
    innerGeo.dispose();
    innerMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    if (glbScene) {
      glbScene.traverse((o) => {
        if (o.isMesh) {
          if (o.geometry) try { o.geometry.dispose(); } catch (_) {}
          if (Array.isArray(o.material)) o.material.forEach((m) => { try { m.dispose(); } catch (_) {} });
          else if (o.material) { try { o.material.dispose(); } catch (_) {} }
        }
      });
    }
  };

  return group;
}
